PreCompact.command:
node -e "
const fs = require('fs');
const path = require('path');
const dir = path.join(process.cwd(), '.claude', 'sessions');
if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
const now = new Date();
const stamp = now.toISOString().replace(/[:.]/g, '-').slice(0, 19);
const file = path.join(dir, stamp + '-precompact.tmp');
fs.writeFileSync(file, JSON.stringify({ event: 'PreCompact', timestamp: now.toISOString(), note: 'State saved before compaction. Resume from this file in next session.' }, null, 2));
console.log('[bks26] PreCompact state saved to', file);
"

